	set.BoolVar(&v.normalize, "normalize", false, "Fold whitespace in text output, preserving case")

	set.StringVar(&v.output, "o", "-", "Explicit atomic output file or '-' for stdout")

	set.BoolVar(&v.strict, "strict", false, "Reject source and extraction diagnostics")

	set.StringVar(&v.root, "root", "", "Explicit allowed source root")

	set.BoolVar(&v.noIncludes, "no-includes", false, "Disable include loading, retaining references")

	set.StringVar(&v.pkg, "package", "man", "Parser context: man, ms or roff")

	set.IntVar(&v.maxBytes, "max-bytes", 8388608, "Cumulative input bytes")

	set.IntVar(&v.maxNodes, "max-nodes", 100000, "Cumulative input AST nodes")

	set.IntVar(&v.maxFiles, "max-files", 256, "Source occurrence cap")

	set.IntVar(&v.maxDepth, "max-depth", 16, "Include depth, ceiling 128")

	set.IntVar(&v.maxExtractNodes, "max-extract-nodes", 200000, "Projection/construction node budget")

	set.IntVar(&v.maxRecords, "max-records", 10000, "Maximum records before a resource error")

	set.IntVar(&v.maxRecordBytes, "max-record-bytes", 16777216, "Materialized record-data budget")

	set.IntVar(&v.maxWork, "max-work", 67108864, "Shared query/construction work budget")

